# Find all enclosed cells using flood fill
def find_enclosed_cells(grid):
    """Find all background cells NOT reachable from grid edge"""
    w, h = len(grid[0]), len(grid)
    visited = [[False]*w for _ in range(h)]

    # Start BFS from all edge cells
    from collections import deque
    queue = deque()
    for r in range(h):
        for c in [0, w-1]:
            if grid[r][c] == 0:
                queue.append((r, c))
    for c in range(w):
        for r in [0, h-1]:
            if grid[r][c] == 0 and visited[r][c] == False:
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        if visited[r][c]:
            continue
        visited[r][c] = True
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                if grid[nr][nc] == 0:
                    queue.append((nr, nc))

    return visited

