from collections import deque

def get_component(grid, start_pos):
    r, c = start_pos
    comp = set()
    queue = deque([start_pos])
    visited = {start_pos}
    while queue:
        cr, cc = queue.popleft()
        comp.add((cr, cc))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr+dr, cc+dc
            if 0<=nr<6 and 0<=nc<21:
                if grid[nr][nc] == 7 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return comp

